mapper.update:
UPDATE ams_leave_request
status = #{status}, audit_by = #{auditBy}, audit_time = #{auditTime}, update_time = #{updateTime},
WHERE id = #{id}

mapper.select:
SELECT , u.username as techName
FROM ams_leave_request t
LEFT JOIN sys_user u ON t.tech_id = u.id

    AND t.store_id = #{storeId}
    AND t.tech_id = #{techId}
    AND u.username LIKE CONCAT('%', #{techName}, '%')
    AND t.status = #{status}
    AND t.type = #{type}
    AND t.create_time >= #{startTime}
    AND t.create_time <= #{endTime}

ORDER BY t.create_time DESC
